+// Custom UnmarshalJSON for CaddyHeaders to handle case-insensitive field names
+func (h *CaddyHeaders) UnmarshalJSON(data []byte) error {
+	// Create a map to hold the raw JSON data
+	var raw map[string]interface{}
+	if err := json.Unmarshal(data, &raw); err != nil {
+		return err
+	}
+
+	// Process each field explicitly to handle case variations
+	for key, value := range raw {
+		// Convert the value to []string
+		var stringArray []string
+		if array, ok := value.([]interface{}); ok {
+			stringArray = make([]string, len(array))
+			for i, item := range array {
+				if str, ok := item.(string); ok {
+					stringArray[i] = str
+				}
+			}
+		}
+
+		switch {
+		case strings.EqualFold(key, "User-Agent"):
+			h.UserAgent = stringArray
+		case strings.EqualFold(key, "Referer"):
+			h.Referer = stringArray
+		case strings.EqualFold(key, "Content-Type"):
+			h.ContentType = stringArray
+		case strings.EqualFold(key, "X-Forwarded-For"):
+			h.XForwardedFor = stringArray
+		case strings.EqualFold(key, "Accept-Language"):
+			h.AcceptLanguage = stringArray
+		}
+	}
+	return nil
+}
