+func ReproduceIssue() {
+	// This is similar to the example in the PR description
+	jsonStr := `{
+		"request": {
+			"headers": {
+				"Referer": ["https://example.com"]
+			}
+		}
+	}`
+
+	var logEntry CaddyLogEntry
+	err := json.Unmarshal([]byte(jsonStr), &logEntry)
+	if err != nil {
+		fmt.Printf("Error unmarshaling: %v\n", err)
+		return
+	}
+
+	referrer := logEntry.Referrer()
+	fmt.Printf("Referrer: '%s'\n", referrer)
